mapper.select:
select ua.id as id,ua.member_id as memberId,ua.orders_sn as ordersSn,ua.vip_id as vipId,
ua.vip_name as vipName,ua.pay_amount as payAmount,ua.orders_status as ordersStatus,ua.pay_type as payType, ua.create_time as createTime,
su.realname as username,su.avatar as userAvatar,su.phone as userPhone
from ums_vip_orders ua
left join sys_user su on su.id = ua.member_id
where 1 = 1 and ua.del_flag!=1

    AND ua.orders_status = #{paramCondition.ordersStatus}


    AND ua.orders_sn = #{paramCondition.ordersSn}


    and (ua.orders_sn like CONCAT('%',#{paramCondition.keyword},'%') or su.realname like CONCAT('%',#{paramCondition.keyword},'%') or su.phone like CONCAT('%',#{paramCondition.keyword},'%'))


    AND ua.member_id = #{paramCondition.memberId}


    AND ua.pay_type = #{paramCondition.payType}

order by ua.create_time desc
